package thaumcraft.utility;
import java.util.*;
import com.mojang.serialization.*;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.material.Fluids;
import net.minecraft.world.level.storage.*;
import net.minecraftforge.common.capabilities.*;
import net.minecraftforge.common.util.LazyOptional;
import net.minecraftforge.fluids.*;
import net.minecraftforge.fluids.capability.*;
import net.minecraftforge.fluids.capability.templates.FluidTank;
public final class WaterDevice extends InventoryDevice {
 public record State(int version,Optional<FluidStack> fluid,ItemStack salt,boolean mix,int cursor){}
 public static final Codec<State> CODEC=RecordCodecBuilder.create(i->i.group(Codec.intRange(1,1).fieldOf("version").forGetter(State::version),FluidStack.CODEC.optionalFieldOf("fluid").forGetter(State::fluid),ItemStack.OPTIONAL_CODEC.fieldOf("salt").forGetter(State::salt),Codec.BOOL.fieldOf("mix").forGetter(State::mix),Codec.intRange(0,74).fieldOf("cursor").forGetter(State::cursor)).apply(i,State::new));
 private Tag unknown;private boolean mix=true;private int ticks,cursor;
 private final FluidTank tank=new FluidTank(5000,s->s.getFluid().defaultFluidState().createLegacyBlock().getBlock()!=Blocks.AIR){protected void onContentsChanged(){if(!loading)sync();}};
 private final IFluidHandler handler=new IFluidHandler(){public int getTanks(){return 1;}public FluidStack getFluidInTank(int t){return t==0&&supported()?tank.getFluid().copy():FluidStack.EMPTY;}public int getTankCapacity(int t){return urn()?1000:5000;}public boolean isFluidValid(int t,FluidStack s){return t==0&&!urn()&&tank.isFluidValid(t,s);}public int fill(FluidStack s,FluidAction a){return supported()&&!isRemoved()&&!urn()?tank.fill(s,a):0;}public FluidStack drain(int n,FluidAction a){return supported()&&!isRemoved()?tank.drain(n,a):FluidStack.EMPTY;}public FluidStack drain(FluidStack s,FluidAction a){return supported()&&!isRemoved()?tank.drain(s,a):FluidStack.EMPTY;}};
 private LazyOptional<IFluidHandler> fluid=LazyOptional.of(()->handler);
 public WaterDevice(BlockPos p,BlockState s){super(UtilityContent.WATER.get(),p,s);}public boolean supported(){return unknown==null;}public boolean urn(){return kind().equals("everfull_urn");}public int amount(){return tank.getFluidAmount();}public IFluidHandler handler(){return handler;}public boolean mix(){return mix;}public void toggle(){if(supported()&&!urn()){mix=!mix;sync();}}public boolean accepts(ItemStack stack){return !urn()&&stack.getItem() instanceof thaumcraft.taint.BathSalts;}
 public void serverTick(){if(!(level instanceof ServerLevel)||!supported()||isRemoved())return;ticks++;if(urn()&&ticks%5==0){distribute();generate();}else if(!urn()&&ticks%40==0&&!level.hasNeighborSignal(worldPosition))placeBath();}
 public int generate(){if(!(level instanceof ServerLevel l)||!urn()||!supported()||amount()>=1000)return 0;int wanted=Math.min(100,1000-amount());float used=thaumcraft.aura.AuraManager.drainVis(l,worldPosition,wanted/1000F,false);int produced=Math.min(wanted,Math.max(0,Math.round(used*1000)));if(produced>0){tank.setFluid(new FluidStack(Fluids.WATER,amount()+produced));sync();}return produced;}
 public int distribute(){if(!(level instanceof ServerLevel l)||!urn()||!supported()||amount()<25)return 0;for(int n=0;n<75;n++){int c=(cursor+n)%75;var p=worldPosition.offset(c/15-2,c/5%3-1,c%5-2);if(p.equals(worldPosition)||!l.hasChunkAt(p))continue;var be=l.getBlockEntity(p);if(be!=null){var dest=be.getCapability(ForgeCapabilities.FLUID_HANDLER,Direction.UP).orElse(null);if(dest!=null){int offered=Math.min(25,amount());int nfill=dest.fill(new FluidStack(Fluids.WATER,offered),IFluidHandler.FluidAction.SIMULATE);if(nfill>0){int paid=dest.fill(new FluidStack(Fluids.WATER,Math.min(offered,nfill)),IFluidHandler.FluidAction.EXECUTE);if(paid>0){tank.drain(Math.min(offered,paid),IFluidHandler.FluidAction.EXECUTE);cursor=(c+1)%75;particles(p);return Math.min(offered,paid);}}}}
  var s=l.getBlockState(p);if(amount()>=333&&(s.is(Blocks.CAULDRON)||s.is(Blocks.WATER_CAULDRON)&&s.getValue(LayeredCauldronBlock.LEVEL)<3)){var next=s.is(Blocks.CAULDRON)?Blocks.WATER_CAULDRON.defaultBlockState().setValue(LayeredCauldronBlock.LEVEL,1):s.cycle(LayeredCauldronBlock.LEVEL);if(thaumcraft.taint.TaintWorld.place(l,p,worldPosition,next,null)){tank.drain(333,IFluidHandler.FluidAction.EXECUTE);cursor=(c+1)%75;particles(p);return 333;}}}return 0;}
 private void particles(BlockPos p){if(level instanceof ServerLevel l)l.sendParticles(net.minecraft.core.particles.ParticleTypes.SPLASH,p.getX()+.5,p.getY()+1,p.getZ()+.5,8,.2,.1,.2,.01);}
 private BlockState bath(){return mix?thaumcraft.taint.TaintContent.PURE.block.get().defaultBlockState():tank.getFluid().getFluid().defaultFluidState().createLegacyBlock();}
 private boolean ingredients(){return amount()>=1000&&(!mix||tank.getFluid().getFluid()==Fluids.WATER&&accepts(inventory.getItem(0))&&!inventory.getItem(0).isEmpty());}
 private boolean validSpot(ServerLevel l,BlockPos p,BlockState target,boolean adjacent){if(!l.hasChunkAt(p)||!l.isInWorldBounds(p)||l.getBlockEntity(p)!=null||!l.getBlockState(p.below()).isFaceSturdy(l,p.below(),Direction.UP))return false;var s=l.getBlockState(p);if(s.equals(target)||!s.canBeReplaced()&&!s.getFluidState().isEmpty()||!s.canBeReplaced())return false;if(target.getFluidState().is(net.minecraft.tags.FluidTags.WATER)&&l.environmentAttributes().getValue(net.minecraft.world.attribute.EnvironmentAttributes.WATER_EVAPORATES,p))return false;if(adjacent){for(var d:Direction.Plane.HORIZONTAL)if(l.hasChunkAt(p.relative(d))&&l.getBlockState(p.relative(d)).equals(target))return true;return false;}return true;}
 public boolean placeBath(){if(!(level instanceof ServerLevel l)||urn()||!supported()||level.hasNeighborSignal(worldPosition)||!ingredients())return false;var target=bath();if(target.isAir())return false;var center=worldPosition.above();if(!l.hasChunkAt(center))return false;boolean spread=l.getBlockState(center).equals(target);for(int i=0;i<(spread?25:1);i++){var p=spread?center.offset(i/5-2,0,i%5-2):center;if(!validSpot(l,p,target,spread))continue;if(!thaumcraft.taint.TaintWorld.place(l,p,worldPosition,target,null))continue;tank.drain(1000,IFluidHandler.FluidAction.EXECUTE);if(mix)inventory.setItem(0,inventory.getItem(0).copyWithCount(inventory.getItem(0).getCount()-1));sync();particles(p);return true;}return false;}
 protected void saveAdditional(ValueOutput out){super.saveAdditional(out);if(unknown!=null)out.store("utility",Codec.PASSTHROUGH,new Dynamic<>(NbtOps.INSTANCE,unknown));else out.store("utility",CODEC,new State(1,tank.isEmpty()?Optional.empty():Optional.of(tank.getFluid()),inventory.getItem(0),mix,cursor));}
 protected void loadAdditional(ValueInput in){super.loadAdditional(in);loading=true;unknown=null;mix=true;cursor=0;tank.setFluid(FluidStack.EMPTY);inventory.setItem(0,ItemStack.EMPTY);var raw=in.read("utility",Codec.PASSTHROUGH);if(raw.isPresent()){var parsed=CODEC.parse(raw.get()).result();if(parsed.isEmpty())unknown=raw.get().convert(NbtOps.INSTANCE).getValue().copy();else{var s=parsed.get();var f=s.fluid().orElse(FluidStack.EMPTY);if(f.getAmount()>(urn()?1000:5000)||urn()&&!f.isEmpty()&&f.getFluid()!=Fluids.WATER||!s.salt().isEmpty()&&(!accepts(s.salt())||s.salt().getCount()>s.salt().getMaxStackSize()))unknown=raw.get().convert(NbtOps.INSTANCE).getValue().copy();else{tank.setFluid(f);inventory.setItem(0,s.salt());mix=s.mix();cursor=s.cursor();}}}loading=false;}
 public <T> LazyOptional<T> getCapability(Capability<T> cap,Direction side){if(cap==ForgeCapabilities.FLUID_HANDLER&&(!urn()||side==Direction.UP))return fluid.cast();if(urn()&&cap==ForgeCapabilities.ITEM_HANDLER)return LazyOptional.empty();return super.getCapability(cap,side);}public void invalidateCaps(){super.invalidateCaps();fluid.invalidate();}public void reviveCaps(){super.reviveCaps();fluid=LazyOptional.of(()->handler);}
}
